#include <iostream>

int main()
{
    const int pagesPerDay{5};
    const int days{3};
    const int totalPages{pagesPerDay * days};

    std::cout << "Total pages: " << totalPages << '\n';
    std::cout << "Without grouping: " << 2 + 3 * 4 << '\n';
    std::cout << "With grouping: " << (2 + 3) * 4 << '\n';
}

#include <iostream>

int main()
{
    const int wholeGroups{7 / 2};
    const int leftOver{7 % 2};
    const double fractional{7.0 / 2};
    const double convertedAfter{7 / 2};

    std::cout << "Whole groups: " << wholeGroups << '\n';
    std::cout << "Left over: " << leftOver << '\n';
    std::cout << "Fractional: " << fractional << '\n';
    std::cout << "Converted after: " << convertedAfter << '\n';
}
